// Generated by collaboration-service (`npm run contract:generate`). Do not edit.
// The room contract lives in collaboration-service under src/contract/.

/**
 * Version of the room contract (state definition and message types).
 * Raise it whenever a change to the contract breaks older frontends.
 */
export const CONTRACT_VERSION = 1;

/** The name under which the Room type is registered. */
export const ROOM_NAME = "collaboration";

/** The options a client passes when creating or joining a Room. */
export type JoinOptions = {
  /** The client's CONTRACT_VERSION. */
  contractVersion: number;
  /** The display name, typed by the person while login is off. */
  name: string;
};

/**
 * Error codes with which the service refuses to create or join a Room.
 * The SDK rejects `create` / `joinById` with an error carrying the code.
 */
export const JoinRefusal = {
  /** No live Room has this code (Colyseus' own code). */
  UNKNOWN_ROOM: 522,
  /** The client was built against another CONTRACT_VERSION. */
  CONTRACT_MISMATCH: 4100,
  /** The Room already has its maximum number of Participants. */
  ROOM_FULL: 4101,
} as const;

/**
 * Messages a client sends to the Room: message type -> payload.
 * Each entry has a handler of the same name in CollaborationRoom's `messages`.
 */
export type ClientMessages = {
  /** Follow another Participant's camera (their session id), or stop with null. */
  spectate: { target: string | null };
  /**
   * The sender's camera, sent only while somebody spectates them, at most
   * CAMERA_UPDATES_PER_SECOND times per second and only when it changed.
   */
  camera: CameraPose;
  /** The sender entered the immersive view of this entity, or left it with null. */
  immersive: { entityId: string | null };
};

/**
 * Messages the Room sends to clients: message type -> payload.
 */
export type ServerMessages = {
  /** The camera of the Participant `from`, forwarded only to those who spectate them. */
  camera: CameraPose & { from: string };
};

/** A camera as world-space pose plus the column-major 4x4 projection matrix (as three.js `toArray()`). */
export type CameraPose = {
  position: [number, number, number];
  quaternion: [number, number, number, number];
  projection: number[];
};

/** How often a spectated Participant sends its camera at most. */
export const CAMERA_UPDATES_PER_SECOND = 30;

// Room state, as plain snapshot types.

export type CollaborationState = {
  participants: Record<string, Participant>;
  hostId: string;
};

export type Participant = {
  name: string;
  color: string;
  spectating: string;
  immersiveEntityId: string;
};
